// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.backup/** * NOUS — Backup data type (Module 12, Pillar 6). * * Strategy §12.6 — flags which data types are included in a backup: * *   - **MEMORIES** — episodic + semantic + procedural memories (Module 3). *   - **CREDENTIALS** — credential vault entries (Module 12). *   - **PRODUCTIVITY** — notes, alarms, reminders (Module 13). *   - **SETTINGS** — user preferences, persona config, feature flags. *   - **ALL** — everything (typically used for full backup). * * Combined as a set (e.g., `setOf(MEMORIES, CREDENTIALS)` for a partial * backup). The [BackupRestoreManager] interprets the set and gathers the * corresponding data sources. */enum class BackupDataType {    MEMORIES,    CREDENTIALS,    PRODUCTIVITY,    SETTINGS,    ALL,}/** * NOUS — Backup result (Module 12, Pillar 6). * * Strategy §12.6 — sealed result of [BackupRestoreManager.createBackup]: * *   - **SUCCESS** — backup completed; includes file path, size, checksum. *   - **FAILED** — backup failed (e.g., no data, disk full, encryption error). *   - **CANCELLED** — user cancelled the backup (e.g., closed the dialog). */sealed interface BackupResult {    /**     * @param filePath absolute path to the .nousbak file.     * @param sizeBytes file size.     * @param checksumSha256 hex-encoded SHA-256 of the file (for integrity     *   verification on restore).     * @param dataType flags that were included.     * @param durationMs wall-clock duration of the backup.     * @param incremental true if this was an incremental backup (only     *   changed data since the last backup).     */    data class Success(        val filePath: String,        val sizeBytes: Long,        val checksumSha256: String,        val dataType: Set<BackupDataType>,        val durationMs: Long,        val incremental: Boolean,    ) : BackupResult    /**     * @param reason machine-readable reason (e.g., "no_data", "disk_full",     *   "encryption_failed", "io_error").     * @param detail human-readable detail for logging.     */    data class Failed(        val reason: String,        val detail: String? = null,    ) : BackupResult    data object Cancelled : BackupResult}/** * NOUS — Restore result (Module 12, Pillar 6). * * Strategy §12.6 — sealed result of [BackupRestoreManager.restoreBackup]: * *   - **SUCCESS** — restore completed; all data types restored. *   - **FAILED** — restore failed entirely (e.g., wrong master password, *     corrupted file). No data was restored. *   - **PARTIAL** — some data types restored, some failed (e.g., *     credentials failed because master password didn't match the credential *     vault key, but memories + settings restored successfully). */sealed interface RestoreResult {    /**     * @param restoredTypes which data types were restored.     * @param durationMs wall-clock duration of the restore.     */    data class Success(        val restoredTypes: Set<BackupDataType>,        val durationMs: Long,    ) : RestoreResult    /**     * @param reason machine-readable reason (e.g., "wrong_master_password",     *   "corrupted_file", "version_mismatch").     * @param detail human-readable detail.     */    data class Failed(        val reason: String,        val detail: String? = null,    ) : RestoreResult    /**     * @param restoredTypes data types that succeeded.     * @param failedTypes data types that failed (with per-type reasons).     * @param durationMs wall-clock duration.     */    data class Partial(        val restoredTypes: Set<BackupDataType>,        val failedTypes: Map<BackupDataType, String>,        val durationMs: Long,    ) : RestoreResult}